head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > openPopup]<br/>지정한 옵션에 맞게 팝업을 생성하여 엽니다.",
    "validation" : [
        "options.useControl(선택) 파라미터를 true 로 설정하면, options.type 속성값이 'browserPopup' 이 아닐때 팝업 상단 타이틀바 영역에 최소화, 최대화, 닫기 버튼을 사용합니다.",
        "options.useControl(선택) 파라미터를 false 로 설정하면, options.type 속성값이 'browserPopup' 이 아닐때 팝업 상단 타이틀바 영역에 최소화, 최대화, 닫기 버튼을 사용하지 않습니다.",
        "options.useControl(선택) 파라미터 생략 시, 기본값 false 로 동작합니다.",
        "options.controls(선택) 파라미터로 options.useControl 속성값이 true 일때 팝업 상단 타이틀바 영역의 최소화, 최대화, 닫기 버튼의 표시 여부를 JSON 객체로 각각 설정합니다.",
        "options.controls(선택) 파라미터 생략 시, 기본값 undefined 로 동작합니다.",
        "options.controls.minimize(선택) 파라미터를 true 로 설정하면, 팝업 상단 타이틀바 영역의 최소화 버튼을 표시합니다.",
        "options.controls.minimize(선택) 파라미터를 false 로 설정하면, 팝업 상단 타이틀바 영역의 최소화 버튼을 표시하지 않습니다.",
        "options.controls.minimize(선택) 파라미터 생략 시, 기본값 true 로 동작합니다.",
        "options.controls.maximize(선택) 파라미터를 true 로 설정하면, 팝업 상단 타이틀바 영역의 최대화 버튼을 표시합니다.",
        "options.controls.maximize(선택) 파라미터를 false 로 설정하면, 팝업 상단 타이틀바 영역의 최대화 버튼을 표시하지 않습니다.",
        "options.controls.maximize(선택) 파라미터 생략 시, 기본값 true 로 동작합니다.",
        "options.controls.close(선택) 파라미터를 true 로 설정하면, 팝업 상단 타이틀바 영역의 닫기 버튼을 표시합니다.",
        "options.controls.close(선택) 파라미터를 false 로 설정하면, 팝업 상단 타이틀바 영역의 닫기 버튼을 표시하지 않습니다.",
        "options.controls.close(선택) 파라미터 생략 시, 기본값 true 로 동작합니다.",
        "options.foldSize(선택) 파라미터로 options.useControl 속성과 options.controls.minimize 속성이 모두 true 일때 팝업이 최소화되면 적용될 팝업의 너비를 JSON 객체로 설정합니다.",
        "options.foldSize.width(선택) 파라미터로 팝업이 최소화 되었을때 적용될 팝업의 너비(Width)를 설정합니다.",
        "options.foldSize.width(선택) 파라미터 생략 시, 기본값 500 으로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    $c.gcm.createLabel('label="[전제] 팝업 너비 400px\n[절차] 타이틀바 최대화 버튼을 누르면 최대화·복원 상태가 바로 출력됩니다. (최대화 중에는 팝업이 부모 화면 버튼을 덮습니다)\n[절차] 타이틀바 최소화·닫기 버튼 클릭 후 팝업 상태 확인 버튼으로 최소화된 팝업 너비·팝업 존재 여부를 확인합니다."', '', 'label1');

    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.popupUrl = "/sample/common_link/p_openPopup_popup.xml";



scwin.out = function (str) {
    wf_body_bottom.getObj("scwin").setReturnValue(str);
};



// 이전 테스트 팝업 정리 (내부 팝업을 정리했으면 true 반환)
scwin.closeAllPopup = function () {
    let list = $p.getAllPopupList().slice();
    let closedInner = false;
    for (let i = 0; i < list.length; i++) {
        let pw = list[i].popupWin;
        try {
            if (pw && typeof pw.forceClose === "function") {
                pw.forceClose();
                closedInner = true;
            } else if (pw && typeof pw.close === "function") {
                pw.close();
            }
        } catch (e) {}
    }
    return closedInner;
};



// 이전 팝업 정리 후 openPopup 실행
// (내부 팝업 정리는 비동기로 끝나므로 300ms 후 연다. 클릭 직후 5초 이내라 browserPopup 도 사용자 동작으로 처리됨)
scwin.runOpenPopup = function (optionList, callback, delay) {
    let fn = function () {
        for (let i = 0; i < optionList.length; i++) {
            $p.openPopup(scwin.popupUrl, optionList[i]);
        }
        if (callback) setTimeout(callback, delay || 1500);
    };
    if (scwin.closeAllPopup()) {
        setTimeout(fn, 300);
    } else {
        fn();
    }
};



// options.id 로 팝업 정보 조회 (Page Scope 적용 시 실행 ID 는 'mf_' 접두사가 붙음)
scwin.findPopup = function (id) {
    let list = $p.getAllPopupList();
    for (let i = list.length - 1; i >= 0; i--) {
        if ((list[i].options.org_id === id || list[i].options.id === id) && list[i].popupWin) return list[i];
    }
    return null;
};



// options.id 로 팝업 최상위 div 조회
scwin.popupEl = function (id) {
    return document.querySelector(".w2popup_window[id$='" + id + "']");
};



// 팝업 내부 요소(타이틀바 버튼 등) 조회
scwin.popupPart = function (id, suffix) {
    let el = scwin.popupEl(id);
    return el ? document.getElementById(el.id + "_" + suffix) : null;
};



scwin.rectStr = function (el) {
    let r = el.getBoundingClientRect();
    return "left " + Math.round(r.left + window.scrollX) + ", top " + Math.round(r.top + window.scrollY) + " / 크기 : " + Math.round(r.width) + " x " + Math.round(r.height);
};

scwin.btn_openPopup_onclick = function () {
    let useControl = par_useControl.getValue();
    let controls = par_controls.getValue();
    let foldSize = par_foldSize.getValue();

    let options = { id: "popup_1", type: "wframePopup", left: "100px", top: "100px", width: "400px", height: "300px", popupName: "openPopup 팝업" };
    if (useControl !== "") options.useControl = (useControl === "true");
    if (controls === "allTrue") {
        options.controls = { minimize: true, maximize: true, close: true };
    } else if (controls !== "") {
        // 지정한 버튼 하나만 false, 나머지 키는 생략
        options.controls = {};
        options.controls[controls] = false;
    }
    if (foldSize === "250") {
        options.foldSize = { width: 250 };
    } else if (foldSize === "empty") {
        options.foldSize = {};
    }

    scwin.runOpenPopup([options], scwin.printResult);
};



scwin.isShown = function (suffix) {
    let el = scwin.popupPart("popup_1", suffix);
    return !!el && el.offsetWidth > 0 && el.offsetHeight > 0;
};



// validation 1~14 판정 출력 (타이틀바 버튼 표시 여부)
scwin.printResult = function () {
    if (!scwin.popupEl("popup_1")) {
        scwin.out("팝업 생성 : false");
        return;
    }
    let pw = scwin.findPopup("popup_1");
    if (pw) {
        pw.popupWin.addEvent("onmaximize", scwin.printMaximize);
        pw.popupWin.addEvent("onrestore", scwin.printMaximize);
    }
    scwin.out("최소화 버튼 : " + scwin.isShown("minimize") + " / 최대화 버튼 : " + (scwin.isShown("maximize") || scwin.isShown("restore")) + " / 닫기 버튼 : " + scwin.isShown("close"));
};



// validation 4, 9, 11 판정 출력 (타이틀바 최대화·복원 버튼 동작)
// 최대화 중에는 팝업이 부모 화면 버튼을 덮어 상태 확인 버튼을 누를 수 없으므로 onmaximize·onrestore 이벤트에서 출력한다.
// 최대화 크기는 브라우저 표시 영역 크기에 따라 달라지므로 표시 영역과 같으면 '화면 전체' 로 출력한다.
scwin.printMaximize = function () {
    let el = scwin.popupEl("popup_1");
    if (!el) return;
    let r = el.getBoundingClientRect();
    let w = Math.round(r.width);
    let h = Math.round(r.height);
    let size = (w === window.innerWidth && h === window.innerHeight) ? "화면 전체" : w + " x " + h;
    scwin.out("최대화 상태 : " + el.classList.contains("w2window_maximized") + " / 팝업 크기 : " + size);
};



// validation 12, 15~17 판정 출력 (최소화 후 팝업 너비, 닫기 버튼 클릭 후 팝업 존재 여부)
scwin.btn_status_onclick = function () {
    let el = scwin.popupEl("popup_1");
    if (!el) {
        scwin.out("팝업 존재 : false");
        return;
    }
    let body = scwin.popupPart("popup_1", "body");
    scwin.out("팝업 너비 : " + Math.round(el.getBoundingClientRect().width) + " / 최소화 상태 : " + (!!body && body.style.display === "none"));
};
